// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAccounts The saved accounts, newest first
	// (GET /api/accounts)
	ListAccounts(w http.ResponseWriter, r *http.Request, params ListAccountsParams)
	// ExportAccounts Export the saved accounts as a file
	// (GET /api/accounts/export)
	ExportAccounts(w http.ResponseWriter, r *http.Request, params ExportAccountsParams)
	// LookupAccounts The saved accounts of a list of emails
	// (POST /api/accounts/lookup)
	LookupAccounts(w http.ResponseWriter, r *http.Request)
	// GetAccountByID One saved account with its secrets
	// (GET /api/accounts/{id})
	GetAccountByID(w http.ResponseWriter, r *http.Request, id ID)
	// ConfirmAccount Mark an account as checked by hand
	// (POST /api/accounts/{id}/confirm)
	ConfirmAccount(w http.ResponseWriter, r *http.Request, id ID)
	// CheckChrome Find Chrome and compare its major with the request shapes
	// (GET /api/checks/chrome)
	CheckChrome(w http.ResponseWriter, r *http.Request)
	// CheckMailbox Log in to the mailbox of an email section
	// (POST /api/checks/mailbox)
	CheckMailbox(w http.ResponseWriter, r *http.Request)
	// GetConfig The effective config of serve mode
	// (GET /api/config)
	GetConfig(w http.ResponseWriter, r *http.Request)
	// SaveConfig Save the config of serve to the config file
	// (PUT /api/config)
	SaveConfig(w http.ResponseWriter, r *http.Request)
	// ValidateConfig Validate a config
	// (POST /api/config/validate)
	ValidateConfig(w http.ResponseWriter, r *http.Request)
	// StreamRunEvents The run state and each change of it, as server-sent events
	// (GET /api/events)
	StreamRunEvents(w http.ResponseWriter, r *http.Request)
	// StreamLogs The log lines of the current or last run of serve, as server-sent events
	// (GET /api/logs)
	StreamLogs(w http.ResponseWriter, r *http.Request, params StreamLogsParams)
	// ListPresets Every run preset of the store, in name order
	// (GET /api/presets)
	ListPresets(w http.ResponseWriter, r *http.Request)
	// SavePreset Save a run preset under its name
	// (POST /api/presets)
	SavePreset(w http.ResponseWriter, r *http.Request)
	// DeletePreset Delete a run preset
	// (DELETE /api/presets/{id})
	DeletePreset(w http.ResponseWriter, r *http.Request, id ID)
	// ListProxies Every proxy of the store with its health, in id order
	// (GET /api/proxies)
	ListProxies(w http.ResponseWriter, r *http.Request)
	// ExportProxies Export the proxies as a proxy file
	// (GET /api/proxies/export)
	ExportProxies(w http.ResponseWriter, r *http.Request)
	// ImportProxies Import the proxies of a proxy file
	// (POST /api/proxies/import)
	ImportProxies(w http.ResponseWriter, r *http.Request)
	// DeleteProxy Delete a proxy
	// (DELETE /api/proxies/{id})
	DeleteProxy(w http.ResponseWriter, r *http.Request, id ID)
	// DisableProxy Disable a proxy
	// (POST /api/proxies/{id}/disable)
	DisableProxy(w http.ResponseWriter, r *http.Request, id ID)
	// EnableProxy Enable a proxy
	// (POST /api/proxies/{id}/enable)
	EnableProxy(w http.ResponseWriter, r *http.Request, id ID)
	// TestProxy Check that the upstream of a proxy accepts a connection
	// (POST /api/proxies/{id}/test)
	TestProxy(w http.ResponseWriter, r *http.Request, id ID)
	// GetRun The state of the current or last run
	// (GET /api/run)
	GetRun(w http.ResponseWriter, r *http.Request)
	// StartRun Start a run with a config
	// (POST /api/run)
	StartRun(w http.ResponseWriter, r *http.Request)
	// StopRun The first stop stage
	// (POST /api/run/stop)
	StopRun(w http.ResponseWriter, r *http.Request)
	// StopRunNow The second stop stage
	// (POST /api/run/stop-now)
	StopRunNow(w http.ResponseWriter, r *http.Request)
	// ListRuns The past and current runs, newest first
	// (GET /api/runs)
	ListRuns(w http.ResponseWriter, r *http.Request, params ListRunsParams)
	// GetRunByID One past or current run
	// (GET /api/runs/{id})
	GetRunByID(w http.ResponseWriter, r *http.Request, id ID)
	// ListRunAttempts The attempts of one run, newest first
	// (GET /api/runs/{id}/attempts)
	ListRunAttempts(w http.ResponseWriter, r *http.Request, id ID, params ListRunAttemptsParams)
	// GetRunLog The log file of one run
	// (GET /api/runs/{id}/log)
	GetRunLog(w http.ResponseWriter, r *http.Request, id ID)
}

