// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAccounts The saved accounts, newest first
	// (GET /api/accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// ExportAccounts Export the saved accounts as a file
	// (GET /api/accounts/export)
	ExportAccounts(ctx context.Context, request ExportAccountsRequestObject) (ExportAccountsResponseObject, error)
	// LookupAccounts The saved accounts of a list of emails
	// (POST /api/accounts/lookup)
	LookupAccounts(ctx context.Context, request LookupAccountsRequestObject) (LookupAccountsResponseObject, error)
	// GetAccountByID One saved account with its secrets
	// (GET /api/accounts/{id})
	GetAccountByID(ctx context.Context, request GetAccountByIDRequestObject) (GetAccountByIDResponseObject, error)
	// ConfirmAccount Mark an account as checked by hand
	// (POST /api/accounts/{id}/confirm)
	ConfirmAccount(ctx context.Context, request ConfirmAccountRequestObject) (ConfirmAccountResponseObject, error)
	// CheckChrome Find Chrome and compare its major with the request shapes
	// (GET /api/checks/chrome)
	CheckChrome(ctx context.Context, request CheckChromeRequestObject) (CheckChromeResponseObject, error)
	// CheckMailbox Log in to the mailbox of an email section
	// (POST /api/checks/mailbox)
	CheckMailbox(ctx context.Context, request CheckMailboxRequestObject) (CheckMailboxResponseObject, error)
	// GetConfig The effective config of serve mode
	// (GET /api/config)
	GetConfig(ctx context.Context, request GetConfigRequestObject) (GetConfigResponseObject, error)
	// SaveConfig Save the config of serve to the config file
	// (PUT /api/config)
	SaveConfig(ctx context.Context, request SaveConfigRequestObject) (SaveConfigResponseObject, error)
	// ValidateConfig Validate a config
	// (POST /api/config/validate)
	ValidateConfig(ctx context.Context, request ValidateConfigRequestObject) (ValidateConfigResponseObject, error)
	// StreamRunEvents The run state and each change of it, as server-sent events
	// (GET /api/events)
	StreamRunEvents(ctx context.Context, request StreamRunEventsRequestObject) (StreamRunEventsResponseObject, error)
	// StreamLogs The log lines of the current or last run of serve, as server-sent events
	// (GET /api/logs)
	StreamLogs(ctx context.Context, request StreamLogsRequestObject) (StreamLogsResponseObject, error)
	// ListPresets Every run preset of the store, in name order
	// (GET /api/presets)
	ListPresets(ctx context.Context, request ListPresetsRequestObject) (ListPresetsResponseObject, error)
	// SavePreset Save a run preset under its name
	// (POST /api/presets)
	SavePreset(ctx context.Context, request SavePresetRequestObject) (SavePresetResponseObject, error)
	// DeletePreset Delete a run preset
	// (DELETE /api/presets/{id})
	DeletePreset(ctx context.Context, request DeletePresetRequestObject) (DeletePresetResponseObject, error)
	// ListProxies Every proxy of the store with its health, in id order
	// (GET /api/proxies)
	ListProxies(ctx context.Context, request ListProxiesRequestObject) (ListProxiesResponseObject, error)
	// ExportProxies Export the proxies as a proxy file
	// (GET /api/proxies/export)
	ExportProxies(ctx context.Context, request ExportProxiesRequestObject) (ExportProxiesResponseObject, error)
	// ImportProxies Import the proxies of a proxy file
	// (POST /api/proxies/import)
	ImportProxies(ctx context.Context, request ImportProxiesRequestObject) (ImportProxiesResponseObject, error)
	// DeleteProxy Delete a proxy
	// (DELETE /api/proxies/{id})
	DeleteProxy(ctx context.Context, request DeleteProxyRequestObject) (DeleteProxyResponseObject, error)
	// DisableProxy Disable a proxy
	// (POST /api/proxies/{id}/disable)
	DisableProxy(ctx context.Context, request DisableProxyRequestObject) (DisableProxyResponseObject, error)
	// EnableProxy Enable a proxy
	// (POST /api/proxies/{id}/enable)
	EnableProxy(ctx context.Context, request EnableProxyRequestObject) (EnableProxyResponseObject, error)
	// TestProxy Check that the upstream of a proxy accepts a connection
	// (POST /api/proxies/{id}/test)
	TestProxy(ctx context.Context, request TestProxyRequestObject) (TestProxyResponseObject, error)
	// GetRun The state of the current or last run
	// (GET /api/run)
	GetRun(ctx context.Context, request GetRunRequestObject) (GetRunResponseObject, error)
	// StartRun Start a run with a config
	// (POST /api/run)
	StartRun(ctx context.Context, request StartRunRequestObject) (StartRunResponseObject, error)
	// StopRun The first stop stage
	// (POST /api/run/stop)
	StopRun(ctx context.Context, request StopRunRequestObject) (StopRunResponseObject, error)
	// StopRunNow The second stop stage
	// (POST /api/run/stop-now)
	StopRunNow(ctx context.Context, request StopRunNowRequestObject) (StopRunNowResponseObject, error)
	// ListRuns The past and current runs, newest first
	// (GET /api/runs)
	ListRuns(ctx context.Context, request ListRunsRequestObject) (ListRunsResponseObject, error)
	// GetRunByID One past or current run
	// (GET /api/runs/{id})
	GetRunByID(ctx context.Context, request GetRunByIDRequestObject) (GetRunByIDResponseObject, error)
	// ListRunAttempts The attempts of one run, newest first
	// (GET /api/runs/{id}/attempts)
	ListRunAttempts(ctx context.Context, request ListRunAttemptsRequestObject) (ListRunAttemptsResponseObject, error)
	// GetRunLog The log file of one run
	// (GET /api/runs/{id}/log)
	GetRunLog(ctx context.Context, request GetRunLogRequestObject) (GetRunLogResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListAccounts operation middleware
func (sh *strictHandler) ListAccounts(w http.ResponseWriter, r *http.Request, params ListAccountsParams) {
	var request ListAccountsRequestObject

	request.Params = params

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListAccounts(ctx, request.(ListAccountsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListAccounts")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListAccountsResponseObject); ok {
		if err := validResponse.VisitListAccountsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

